test('Rapid Fire changes only active ranged cast time and swing cadence; duration expires without consuming the aura',()=>{
 const a=scenario('hunter',3045,{acceptExternalReference:true,cooldownMs:300000}); const rapid=compileReferenceRank(a).action;assert.deepEqual(rapid.targets,['self']);assert.equal(rapid.costs[0].amount,100);
 assert.throws(()=>compileReferenceRank({...a,policy:{...a.policy,rapidFireModel:{castReductionPct:100}}}),/cast reduction/);
 const aim=scenario('hunter',20904,{acceptExternalReference:true,cooldownMs:0,rangedModel:{attackPower:100,weaponPolicy:'actual-swing',ammoUsesActualSpeed:true,missPct:0,critPct:0,blockPct:0,blockValue:0,critSuppressionPct:0,criticalMultiplier:2,order:['miss','dodge','parry','block','glance','crit'],ammoPerShot:0}});const {action,stats}=compileReferenceRank(aim);
 const autos=[{id:'ranged',actorId:'player',source:'Auto Shot',intervalMs:2800,firstAtMs:2800,castPolicy:'continue',hasteStat:'rangedHasteFactor',hastePolicy:'preserve-progress',minRangeYards:8,maxRangeYards:35,effects:[{kind:'damage',when:'always',school:'physical',formula:{min:1,max:1,terms:[],multiplier:1},outcomes:[{name:'hit',probability:1,multiplier:1,landed:true}],mitigation:0,flatReduction:0,threat:null}]}];
 const r=createExplicitClassEncounter({mode:'research',provenance:'synthetic Rapid Fire test',classId:'hunter',level:60,seed:42,durationMs:22000,decisionIntervalMs:50,pools:{mana:{current:1e5,max:1e5}},units:[{id:'player',maxHealth:1000},{id:'boss',maxHealth:1e7}],playerId:'player',primaryId:'boss',targetIds:['boss'],allyIds:[],stats:{player:stats},classContext:{},geometry:{player:{player:{distance:0,position:'self'},boss:{distance:20,position:'behind'}}},actions:[rapid,action],rows:[{ability:'Rapid Fire',target:'self',conditions:[]},{ability:'Aimed Shot',target:'primary',conditions:[]}],autos,regeneration:[]}).run();
 const casts=r.events.filter(x=>x.type==='action-start'&&x.ability==='Aimed Shot');assert.ok(casts.filter(x=>x.time<15000).length>1);assert.ok(casts.filter(x=>x.time<15000).every(x=>x.castMs===Math.round(action.castMs*.7)));assert.ok(casts.filter(x=>x.time>=15000).length>0);assert.ok(casts.filter(x=>x.time>=15000).every(x=>x.castMs===action.castMs));
 const swings=r.events.filter(x=>x.type==='damage'&&x.source==='Auto Shot').map(x=>x.time);assert.equal(swings[0],2000);assert.equal(swings[1]-swings[0],2000);assert.equal(swings.at(-1)-swings.at(-2),2800);
});


