test('reference ranks have unique class/spell identity and retain observed source fields after consolidation',()=>{const keys=REFERENCE_RANKS.map(r=>r.classId+':'+r.spellId);assert.equal(new Set(keys).size,keys.length);const blast=referenceRank('mage',13021),siphon=referenceRank('warlock',18881);assert.equal(blast.record.fields.baseMin,462);assert.equal(blast.record.fields.baseMax,545);assert.equal(siphon.record.fields.baseTick,45);assert.equal(siphon.record.fields.classicTotal,450);assert.ok(blast.requiredPolicy.includes('areaModel'));assert.ok(siphon.requiredPolicy.includes('siphonLifeModel'));assert.equal(blast.status,'reference-implementation');assert.equal(siphon.status,'reference-implementation');});


test('Drain Soul separates the initial payment from each actual paid channel tick, including early interruption',()=>{const a=scenario('warlock',51687,{acceptExternalReference:true,costOverride:135,channelApplicationPolicy:'independent-ticks',channelTickAtEnd:true,cooldownMs:60000});const {action,stats}=compileReferenceRank(a);assert.equal(action.costs[0].amount,135);assert.deepEqual(action.channelTickCosts,[{resource:'mana',amount:65}]);assert.equal(action.effects[0].formula.min,950/6);const make=(mana,health=1e7,grant=false,eligible=[])=>createExplicitClassEncounter({mode:'research',provenance:'channel fee fixture',classId:'warlock',level:60,seed:42,durationMs:7000,decisionIntervalMs:50,pools:{mana:{current:mana,max:mana},...(grant?{soulShards:{current:0,max:3}}:{})},units:[{id:'player',maxHealth:1000},{id:'boss',maxHealth:health}],playerId:'player',primaryId:'boss',targetIds:['boss'],allyIds:[],stats:{player:stats},classContext:{},geometry:{player:{boss:{distance:20,position:'front'}}},actions:[{...action,...(grant?{channelDeathReward:{resource:'soulShards',amount:1,requiresDamage:true}}:{})}],rows:[{ability:'Drain Soul',target:'primary',conditions:[]}],autos:[],regeneration:[],...(grant?{soulShardEligibleTargets:eligible}:{})}).run();const full=make(525);assert.equal(full.resources.mana.current,0);assert.equal(full.events.filter(e=>e.type==='channel-tick').length,6);const partial=make(265);assert.equal(partial.resources.mana.current,0);assert.equal(partial.events.filter(e=>e.type==='channel-tick').length,2);assert.ok(partial.events.some(e=>e.type==='channel-interrupted'&&e.reason==='insufficient channel resource'));const kill=make(525,1,true,['boss']);assert.equal(kill.resources.soulShards.current,1);assert.equal(kill.resources.mana.current,325);assert.equal(make(525,1,true,[]).resources.soulShards.current,0);});

test('Soul Siphon caps its dynamic owned Affliction bonus at four and does not treat drains as Affliction debuffs',()=>{const a=scenario('warlock',51687,{acceptExternalReference:true,costOverride:135,channelApplicationPolicy:'independent-ticks',channelTickAtEnd:true});a.build.talents['348']=3;const {action}=compileReferenceRank(a);assert.equal(action.effects[0].ownedAfflictionBonus.fraction,.06);assert.equal(action.effects[0].ownedAfflictionBonus.cap,4);assert.ok(action.effects[0].ownedAfflictionBonus.names.includes('Corruption'));assert.ok(!action.effects[0].ownedAfflictionBonus.names.includes('Drain Life'));});


test('Dark Harvest modifies only owned Affliction timers on its channel target and resets on death',()=>{const a=scenario('warlock',52552,{acceptExternalReference:true,costOverride:200,channelApplicationPolicy:'independent-ticks',channelTickAtEnd:true,cooldownMs:30000});const {action,stats}=compileReferenceRank(a);assert.equal(action.effects[0].formula.min,1150/8);assert.equal(action.resetCooldownOnTargetDeath,true);const make=(health,expiryPolicy)=>{const e=createExplicitClassEncounter({mode:'research',provenance:'Dark Harvest lifecycle fixture',classId:'warlock',level:60,seed:42,durationMs:12000,decisionIntervalMs:50,pools:{mana:{current:5000,max:5000}},units:[{id:'player',maxHealth:1000},{id:'boss',maxHealth:health},{id:'other',maxHealth:1e7},{id:'friend',maxHealth:1000}],playerId:'player',primaryId:'boss',targetIds:['boss','other'],allyIds:['friend'],stats:{player:stats},classContext:{},geometry:{player:{boss:{distance:20,position:'front'},other:{distance:20,position:'front'},friend:{distance:20,position:'front'}}},actions:[{...action,darkHarvest:{...action.darkHarvest,expiryPolicy}}],rows:[{ability:'Dark Harvest',target:'primary',conditions:[]}],autos:[],regeneration:[]}),timings={};for(const [id,ownerId,targetId,name] of [['own','player','boss','Corruption'],['external','friend','boss','Corruption'],['different-target','player','other','Siphon Life'],['non-affliction','player','boss','Immolate']]){timings[id]=[];e.auras.apply({id,name,ownerId,targetId,kind:'debuff',durationMs:12000,maxStacks:1,stacks:1,stackPolicy:'replace',refreshPolicy:'refresh'});e.periodic.apply({id,durationMs:12000,intervalMs:3000,tickAtExpiry:true,tickPriority:10,expirePriority:20,refresh:'restart',snapshot:null,onTick:p=>timings[id].push(p.time)});}const result=e.run();return {result,timings};};const fixed=make(1e7,'fixed-expiry');assert.deepEqual(fixed.timings.own,[2100,4200,6300,8571,11571]);for(const id of ['external','different-target','non-affliction'])assert.deepEqual(fixed.timings[id],[3000,6000,9000,12000]);const compressed=make(1e7,'preserve-tick-count');assert.deepEqual(compressed.timings.own,[2100,4200,6300,8571]);const death=make(1,'fixed-expiry');assert.ok(death.result.events.some(e=>e.type==='cooldown-reset'&&e.abilityId==='warlock:dark-harvest'));assert.ok(death.result.events.some(e=>e.type==='channel-interrupted'&&e.reason==='target died'));});


test('Molten Blast refreshes only landed owned Flame Shock and handles explicit refresh bonus',()=>{const a=scenario('shaman',36921,{acceptExternalReference:true,costOverride:210,phase:3,cooldownMs:60000});a.build.talents['226']=2;const {action,stats}=compileReferenceRank(a);assert.equal(action.effects[1].bonusFraction,.6);const e=createExplicitClassEncounter({mode:'research',provenance:'molten refresh fixture',classId:'shaman',level:60,seed:42,durationMs:7000,decisionIntervalMs:50,pools:{mana:{current:5000,max:5000}},units:[{id:'player',maxHealth:1000},{id:'boss',maxHealth:1e7},{id:'friend',maxHealth:1000}],playerId:'player',primaryId:'boss',targetIds:['boss'],allyIds:['friend'],stats:{player:stats},classContext:{},geometry:{player:{boss:{distance:20,position:'front'}}},actions:[{...action,effects:[{...action.effects[0],outcomes:[{name:'hit',probability:1,multiplier:1,landed:true}]},action.effects[1]]}],rows:[{ability:'Molten Blast',target:'primary',conditions:[]}],autos:[],regeneration:[]});const ticks={};for(const [id,ownerId] of [['own','player'],['other','friend']]){ticks[id]=[];e.auras.apply({id,name:'Flame Shock',ownerId,targetId:'boss',kind:'debuff',durationMs:6000,maxStacks:1,stacks:1,stackPolicy:'replace',refreshPolicy:'refresh'});e.periodic.apply({id,durationMs:6000,intervalMs:3000,tickAtExpiry:true,tickPriority:10,expirePriority:20,refresh:'restart',snapshot:null,onTick:p=>ticks[id].push(p.time)});}const result=e.run();assert.deepEqual(ticks.own,[3000,6000]);assert.deepEqual(ticks.other,[3000,6000]);assert.ok(result.auras.find(x=>x.id==='own').activeMs>result.auras.find(x=>x.id==='other').activeMs);assert.ok(result.events.some(x=>x.type==='damage'&&x.source==='Molten Blast (refresh)'));});

