test('Mend Pet channels actual healing only to living pet and applies the Improved Mend Pet model',()=>{const a=scenario('hunter',13544,{acceptExternalReference:true,costOverride:480,channelTickAtEnd:true,cooldownMs:60000});a.build.talents['383']=2;const {action,stats}=compileReferenceRank(a);assert.equal(action.effects[0].formula.min,245);assert.equal(action.effects[0].formula.multiplier,1.4);assert.equal(action.effects[1].chance,.5);assert.deepEqual(action.targets,['pet']);const e=createExplicitClassEncounter({mode:'research',provenance:'pet heal fixture',classId:'hunter',level:60,seed:42,durationMs:6000,decisionIntervalMs:50,pools:{mana:{current:1000,max:1000}},units:[{id:'player',maxHealth:1000},{id:'boss',maxHealth:1e7},{id:'pet',maxHealth:1e5,health:1}],playerId:'player',primaryId:'boss',targetIds:['boss'],allyIds:[],petId:'pet',stats:{player:stats,pet:{}},classContext:{},geometry:{player:{pet:{distance:5,position:'front'},boss:{distance:20,position:'front'}}},actions:[action],rows:[{ability:'Mend Pet',target:'pet',conditions:[]}],autos:[],regeneration:[]}).run();assert.equal(e.events.filter(x=>x.type==='channel-tick').length,5);assert.equal(e.events.filter(x=>x.type==='heal'&&x.targetId==='pet').length,5);assert.equal(e.events.filter(x=>x.type==='heal'&&x.targetId!=='pet').length,0);assert.equal(e.resources.mana.current,520);});

test('Bestial Wrath uses base mana and buffs only the companion for 18 seconds',()=>{const a=scenario('hunter',19574,{acceptExternalReference:true});const {action,stats}=compileReferenceRank(a);assert.equal(action.gcdMs,0);assert.equal(action.costs[0].amount,120);const h=[{name:'hit',probability:1,multiplier:1,landed:true}];const auto=(id,actorId)=>({id,actorId,source:id,intervalMs:1000,firstAtMs:1000,castPolicy:'continue',minRangeYards:0,maxRangeYards:30,effects:[{kind:'damage',when:'always',school:'physical',formula:{min:100,max:100,terms:[],multiplier:1},outcomes:h,mitigation:0,flatReduction:0,threat:null}]});const e=createExplicitClassEncounter({mode:'research',provenance:'pet buff fixture',classId:'hunter',level:60,seed:42,durationMs:21000,decisionIntervalMs:50,pools:{mana:{current:1000,max:1000}},units:[{id:'player',maxHealth:1000},{id:'boss',maxHealth:1e7},{id:'pet',maxHealth:1000}],playerId:'player',primaryId:'boss',targetIds:['boss'],allyIds:[],petId:'pet',stats:{player:stats,pet:{}},classContext:{},geometry:{player:{pet:{distance:5,position:'front'},boss:{distance:20,position:'front'}},pet:{boss:{distance:3,position:'front'}}},actions:[action],rows:[{ability:'Bestial Wrath',target:'pet',conditions:[]}],autos:[auto('owner','player'),auto('pet-auto','pet')],regeneration:[]}).run();assert.ok(e.events.filter(x=>x.type==='damage'&&x.actorId==='player').every(x=>x.raw===100));assert.equal(e.events.find(x=>x.type==='damage'&&x.actorId==='pet').raw,140);assert.equal(e.events.filter(x=>x.type==='damage'&&x.actorId==='pet').at(-1).raw,100);});

test('Hunter mark dynamically affects ranged weapon AP but not fixed melee damage',()=>{const a=scenario('hunter',14325,{acceptExternalReference:true,costOverride:60});const {action,stats}=compileReferenceRank(a);const h=[{name:'hit',probability:1,multiplier:1,landed:true}];const auto=(id,coef)=>({id,actorId:'player',source:id,intervalMs:1000,firstAtMs:1000,castPolicy:'continue',minRangeYards:0,maxRangeYards:30,effects:[{kind:'damage',when:'always',school:'physical',formula:{min:100,max:100,terms:[],multiplier:1,...(coef?{targetRangedAPCoefficient:coef}:{})},outcomes:h,mitigation:0,flatReduction:0,threat:null}]});const e=createExplicitClassEncounter({mode:'research',provenance:'mark fixture',classId:'hunter',level:60,seed:42,durationMs:3000,decisionIntervalMs:50,pools:{mana:{current:1000,max:1000}},units:[{id:'player',maxHealth:1000},{id:'boss',maxHealth:1e7}],playerId:'player',primaryId:'boss',targetIds:['boss'],allyIds:[],stats:{player:stats},classContext:{},geometry:{player:{boss:{distance:20,position:'front'}}},actions:[action],rows:[{ability:'Hunter’s Mark',target:'primary',conditions:[]}],autos:[auto('ranged',2.8/14),auto('melee',0)],regeneration:[]}).run();assert.ok(e.events.filter(x=>x.type==='damage'&&x.source==='ranged').every(x=>Math.abs(x.raw-122)<1e-8));assert.ok(e.events.filter(x=>x.type==='damage'&&x.source==='melee').every(x=>x.raw===100));});


test('Lacerate waits for a target-bound owner crit and converts 20% of landed direct damage into four bleed ticks',()=>{const a=scenario('hunter',48049,{acceptExternalReference:true});a.policy.physical={...a.policy.physical,position:'side'};const {action,stats}=compileReferenceRank(a);assert.equal(action.effects[0].formula.terms[0].coefficient,.4);assert.ok(Math.abs(action.effects[0].formula.multiplier-1.15)<1e-9);const guaranteed=[{name:'hit',probability:1,multiplier:1,landed:true}],crit=[{name:'crit',probability:1,multiplier:2,landed:true}];const auto={id:'mainhand',source:'fixture crit',actorId:'player',intervalMs:30000,firstAtMs:1000,castPolicy:'continue',minRangeYards:0,maxRangeYards:5,effects:[{kind:'damage',when:'always',school:'physical',formula:{min:10,max:10,terms:[],multiplier:1},outcomes:crit,mitigation:0,flatReduction:0,threat:null}]};const e=createExplicitClassEncounter({mode:'research',provenance:'lacerate fixture',classId:'hunter',level:60,seed:42,durationMs:10000,decisionIntervalMs:50,pools:{mana:{current:1000,max:1000}},units:[{id:'player',maxHealth:1000},{id:'boss',maxHealth:1e7}],playerId:'player',primaryId:'boss',targetIds:['boss'],allyIds:[],stats:{player:stats},classContext:{},geometry:{player:{boss:{distance:3,position:'side'}}},actions:[{...action,effects:[{...action.effects[0],formula:{min:100,max:100,terms:[],multiplier:1},outcomes:guaranteed,mitigation:0,armourModel:{attackerLevel:60,armour:0}},action.effects[1]]}],rows:[{ability:'Lacerate',target:'primary',conditions:[]}],autos:[auto],regeneration:[]}).run();assert.equal(e.events.filter(x=>x.type==='action-start'&&x.ability==='Lacerate').length,1);assert.equal(e.events.filter(x=>x.type==='damage'&&x.source==='Lacerate (bleed)').length,4);assert.equal(e.events.filter(x=>x.type==='damage'&&x.source==='Lacerate (bleed)').reduce((n,x)=>n+x.raw,0),20);});

test('Intimidation grants pet threat after the next eligible landed attack even if the stun is immune',()=>{const a=scenario('hunter',19577,{acceptExternalReference:true,costOverride:50});const {action,stats}=compileReferenceRank(a);const e=createExplicitClassEncounter({mode:'research',provenance:'pet threat fixture',classId:'hunter',level:60,seed:42,durationMs:4000,decisionIntervalMs:50,pools:{mana:{current:1000,max:1000}},units:[{id:'player',maxHealth:1000},{id:'boss',maxHealth:1e7},{id:'pet',maxHealth:1000}],playerId:'player',primaryId:'boss',targetIds:['boss'],allyIds:[],petId:'pet',stats:{player:stats,pet:{}},classContext:{},geometry:{player:{boss:{distance:20,position:'front'}},pet:{boss:{distance:3,position:'front'}}},actions:[action],rows:[{ability:'Intimidation',target:'primary',conditions:[]}],autos:[{id:'pet-auto',source:'pet-auto',actorId:'pet',intervalMs:1000,firstAtMs:1000,castPolicy:'continue',minRangeYards:0,maxRangeYards:5,effects:[{kind:'damage',when:'always',school:'physical',formula:{min:100,max:100,terms:[],multiplier:1},outcomes:[{name:'hit',probability:1,multiplier:1,landed:true}],mitigation:0,flatReduction:0,threat:{coefficient:1,flat:0,multipliers:[],distribution:'each'}}]}],regeneration:[]}).run();const events=e.events.filter(x=>x.type==='damage'&&x.actorId==='pet');assert.deepEqual(events.map(x=>x.generatedThreat),[100,150,150,150]);assert.ok(e.events.some(x=>x.type==='attack-result'&&x.source==='Intimidation (stun)'&&!x.landed));assert.ok(!e.auras.some(x=>x.name==='Intimidation (stun)'));});

